import{_ as s}from"./chunks/ub_memory_allocation.CuuYgpT8.js";import{_ as p,o as n,a as l,b as t}from"./app.DKoEZOcr.js";const c="/ascendc.github.io/pr/5487/assets/thread_structure_62.gQmaczJG.png",v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMT API","link":"/api/SIMT-API/SIMT-API"},{"text":"SIMD与SIMT混合编程简介","link":"/api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/SIMD_SIMT_hybrid_programming_intro"},{"text":"编程模型","link":"/api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/programming_model"}]},"headers":[],"relativePath":"api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/programming_model.md","filePath":"api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/programming_model.md","outlineHeaders":[{"level":2,"title":"适用场景","slug":"适用场景","link":"#适用场景"},{"level":2,"title":"线程架构","slug":"线程架构","link":"#线程架构"},{"level":2,"title":"Warp执行机制","slug":"Warp执行机制","link":"#Warp执行机制"},{"level":2,"title":"UB划分","slug":"UB划分","link":"#UB划分"},{"level":3,"title":"UB内存空间说明","slug":"UB内存空间说明","link":"#UB内存空间说明"}],"lastUpdated":1787050286000}'),i={name:"api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/programming_model.md"};function e(d,a,r,h,o,_){return n(),l("div",null,[...a[0]||(a[0]=[t('<div><article class="markdown-body"><h1>编程模型</h1><h2 id="适用场景">适用场景<a class="header-anchor" href="#适用场景">​</a></h2><p>在SIMD与SIMT混合编程中，SIMT能够简化复杂算子与不规则控制流的开发；而SIMD基于向量寄存器与指令，实现高效的数据并行处理，即单指令处理多数据，提升每周期的吞吐量。SIMD与SIMT混合编程支持开发者根据算子特征进行精细化映射：规则的逐元素elementwise操作通过SIMD获得高带宽和高算力利用率，不规则或包含分支的计算通过SIMT来缓解发散和控制复杂度。在系统层面，这有利于提高硬件利用率和能效；同时，也更便于进行算子融合和数据复用等优化。同一个算子中既包含SIMD擅长的连续规整计算，也包含SIMT擅长的离散访问等任务，从而在同一算子中同时利用SIMD和SIMT的优势。</p><h2 id="线程架构">线程架构<a class="header-anchor" href="#线程架构">​</a></h2><p>SIMT编程模型采用分层的抽象线程组织结构，示意图如下图所示，从顶层到底层依次为：Grid（线程块网格）、Thread Block（线程块）、Warp（线程束）和Thread（线程）。这种层次化的设计使得开发者可以方便地将并行计算问题映射到硬件资源上。</p><p><strong>图1</strong> 线程结构示意图</p><p><img src="'+c+`" alt title="线程结构示意图-62"></p><p><strong>Thread（线程）</strong></p><p>线程是整个架构中的最小单元，每个线程独立完成计算任务，拥有独立的寄存器和栈空间。</p><p><strong>Thread Block（线程块）</strong></p><p>Thread Block是Grid的组成单元，由若干线程组成（最大2048个线程）。使用内置变量<a href="extended_syntax/builtin_variables.html#blockdim">blockDim</a>来表示一个Thread Block启用的线程数量。在SIMD与SIMT混合编程场景中，Thread Block有以下特点：</p><ul><li>使用<a href="extended_syntax/kernel_function_config.html#asc_vf_call%E8%B0%83%E7%94%A8">asc_vf_call</a>调用SIMT VF时，需显式指定Thread Block的维度信息；</li><li>同一Thread Block内的线程可以访问共享内存，即Unified Buffer（UB），以实现数据交互；Thread Block内的线程可通过同步机制实现协作；</li><li>在SIMT函数定义时可使用<a href="extended_syntax/kernel_function_config.html#__launch_bounds__n">__launch_bounds__()</a>配置最大线程数，用于编译期底层对寄存器资源进行预分配。</li></ul><p><strong>Grid（线程块网格）</strong></p><p>Grid是SIMT线程层次结构的最顶层，由多个Thread Block组成。使用内置变量<a href="extended_syntax/builtin_variables.html#griddim">gridDim</a>来表示Grid中启用的线程块数量。在SIMD与SIMT混合编程场景，Grid有以下特征：</p><ul><li>Grid的维度配置由用户设置启动的AIV核数决定，核函数（Kernel）执行期间不可更改；</li><li>Grid中的所有线程块具有相同的尺寸和维度配置；</li><li>同一Grid中的线程块相互独立，按任意顺序执行；</li></ul><p>限制说明如下：</p><ul><li>Grid中线程块总数不能超过65535。</li><li>由于gridDim实际就是用户配置的启动AIV核数，当设置的核数超过物理核数时，头尾开销会增大，强烈建议启动的AIV核数小于物理核数。</li></ul><p><strong>线程索引</strong></p><p>每个线程都有唯一的标识，开发者可以通过内置变量获取线程的信息，从而确定每个线程负责处理的数据，相关内置变量如下表所示：</p><table><thead><tr><th>内置变量</th><th>说明</th><th>数据类型</th><th>约束</th></tr></thead><tbody><tr><td>gridDim</td><td>Grid的维度大小。</td><td>dim3</td><td>gridDim.x &lt;= 65535；gridDim.y、gridDim.z必须为1</td></tr><tr><td>blockDim</td><td>Thread Block的维度大小。</td><td>dim3</td><td>blockDim.x * blockDim.y * blockDim.z &lt;= 2048</td></tr><tr><td>blockIdx</td><td>当前Thread Block在Grid中的索引。</td><td>dim3</td><td>无</td></tr><tr><td>threadIdx</td><td>当前线程在Thread Block内的索引。</td><td>dim3</td><td>无</td></tr></tbody></table><p>各Thread Block可通过线程块索引blockIdx进行标识，各线程可通过线程块内线程索引threadIdx进行标识。对于一维Grid和Block，索引计算公式为：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">int</span><span class="w"> </span><span class="n">idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
</code></pre></div><p>对于二维Grid和Block，索引计算公式为：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">int</span><span class="w"> </span><span class="n">x_index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="kt">int</span><span class="w"> </span><span class="n">y_index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">y</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">y</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">y</span><span class="p">;</span>
</code></pre></div><h2 id="Warp执行机制">Warp执行机制<a class="header-anchor" href="#Warp执行机制">​</a></h2><p>Warp是SIMT架构中基本的调度和执行单位。每个Warp包含32个线程，这些线程从相同的程序地址开始执行，拥有各自的指令地址计数器和寄存器状态，并且可以选择分支独立执行。在一个Thread Block内，所有线程按线性顺序被硬件自动划分为每32个线程一组的Warp，同一Warp内的所有线程执行同一条指令。</p><p>Warp内的线程虽然执行同一段代码，但可通过条件分支进入不同的执行路径，这种情况称为分支发散（Warp Divergence）。当Warp中的32个线程均执行相同的代码分支时，硬件利用率最高；一旦发生分支发散，硬件会串行执行每个分支路径，只有进入当前分支的线程（即活跃线程）会被执行，其余线程则被屏蔽，从而导致Warp执行效率下降。此外，同一Warp内的线程相互独立，彼此不能存在依赖关系。</p><p>Thread Block的线程数建议设置为32的整数倍。若线程数未满足该要求，最后一个Warp将包含不足32个线程，导致该Warp内存在空闲线程通道，进而降低执行效率。</p><h2 id="UB划分">UB划分<a class="header-anchor" href="#UB划分">​</a></h2><p>UB是同一线程块内所有线程均可访问的内存空间，位于每个AIV内部。UB内存空间总大小为256KB，参考<a href="#fig9500834165913">图2</a>，按功能划分为四个主要区域，从低地址向高地址依次为静态内存、动态内存、预留空间、Data Cache。</p><p><strong>图2</strong> UB内存分配图<span id="fig9500834165913"></span><br><img src="`+s+`" alt title="UB内存分配图-63"></p><h3 id="UB内存空间说明">UB内存空间说明<a class="header-anchor" href="#UB内存空间说明">​</a></h3><ol><li><p>静态内存：从内存的起始地址分配一段指定大小的内存空间，其大小在编译时确定，不可动态修改。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 静态内存通过数组分配，例如：</span>
<span class="n">__ubuf__</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="n">static_buf</span><span class="p">[</span><span class="mi">1024</span><span class="p">];</span>
</code></pre></div></li><li><p>动态内存：位于静态内存之后，通过<a href="extended_syntax/kernel_function_config.html#%E8%B0%83%E7%94%A8">&lt;&lt;&lt;...&gt;&gt;&gt;</a>中参数dyn_ub_size指定大小的动态内存空间，可通过以下方式申请使用：</p><ul><li><p>使用动态数组分配。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 动态内存通过动态数组分配，例如：</span>
<span class="k">extern</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="n">dynamic_buf</span><span class="p">[];</span>
</code></pre></div></li><li><p>通过LocalMemAllocator的Alloc接口申请。</p></li></ul><p>由于申请动态内存时均从静态内存结束位置之后开始分配，如果同时使用可能会导致地址空间重叠，从而引发未定义行为，因此只能选择其中一种方法进行申请。</p></li><li><p>预留空间：系统预留空间，大小固定为8KB。</p></li><li><p>Data Cache：SIMT专有的Data Cache空间，UB内扣除静态内存、动态内存以及预留空间以后，剩余内存大小为Data Cache，Data Cache最小为32KB，剩余空间超过128KB时Data Cache大小固定为128KB，具体计算公式为：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>DataCache = UB总大小（256KB） - 静态内存 - 动态内存 - 预留空间(8KB)
</code></pre></div><p>若DataCache小于32KB，会出现校验报错。</p></li></ol></article></div>`,1)])])}const I=p(i,[["render",e]]);export{v as __pageData,I as default};
